  ok('K-10', 'its standard is a link to a metadata-only reference, and it is used in the critical-distance note', await count(p, '[data-testid=kn-related] a[href="#/knowledge/z1.iso-3382-2"]') === 1 && await count(p, '[data-testid=kn-usedin] a[href="#/knowledge/k2.rt60.critical-distance"]') === 1);
  await shot(p, 'object-desktop');
