  await to(p, '#/knowledge/z1.iso-3382-2');
  const z1 = await text(p, 'main'); ok('K-12', 'a standard is a title and a number: its text is not held, and the page says so', /ISO 3382-2 — Acoustics/.test(z1) && /The text of this standard is not held here/.test(z1) && /Title and number only/.test(z1) && await count(p, '[data-testid=kn-body]') === 0 && await count(p, '[data-testid=kn-worked]') === 0);
  await to(p, '#/knowledge/k2.aec.tree'); const tree = await p.locator('[data-testid=kn-tree] > li').count();
