  const ev = await events(p); ok('R-09', 'every step, every change at the source, the refusals and the disconnect are in the ledger', ['connect', 'authorize', 'scope', 'preview', 'classify', 'import', 'validate', 'index', 'approve', 'surface', 'sync', 'source', 'disconnect'].every((x) => ev.some((e) => e.type === `knowledge.source.${x}` && e.outcome === 'ALLOWED')) && ev.filter((e) => e.outcome === 'DENIED' && e.type === 'knowledge.source.approve').length >= 3 && ev.every((e) => e.type.startsWith('knowledge.source.') ? /simulated source|refused/.test(e.detail) : true), JSON.stringify([...new Set(ev.map((e) => e.type))]));
  // who may do what on the sources page
