  ok('H-08', 'with no source at all it abstains and invents nothing', n.kind === 'abstain' && /No approved source I do not have an approved source for that\.$/.test(n.t || '') && n.cites === 0, JSON.stringify(n));
  await load(p, `#/ask?q=${encodeURIComponent('Which rooms are free now?')}`); ok('H-09', 'a question Core has a prepared answer for is answered by Core as before', await count(p, '[data-testid=ask-knowledge]') === 0);
