  await as(p, 'syseng', '#/search?q=air%20noise'); const c = await p.locator('[data-testid=sp-knowledge] li').evaluateAll((l) => l.map((x) => [x.dataset.id, x.dataset.candidate, x.querySelector('.ui-tag').textContent]));
  ok('H-11', 'an unverified object is offered only to a reviewer, labelled a candidate', c.some((x) => x[0] === 'cd.cand.obs-air' && x[1] === 'yes' && x[2] === 'Candidate — not fact'), JSON.stringify(c));
  await as(p, 'service', '#/search?q=air%20noise'); ok('H-12', 'and to nobody else', await count(p, '[data-testid=sp-knowledge] li[data-candidate=yes]') === 0);
  await to(p, '#/search?q=zzqx'); ok('H-13', 'a search with no knowledge shows no knowledge section at all', await count(p, '[data-testid=sp-knowledge]') === 0);
